"""Standalone runner setup using the authoring application's visual language."""

SETUP_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ARISEKit local runner</title>
<style>
:root{color-scheme:light dark;--bg:#fff;--surface:#fff;--subtle:#f4f4f5;--text:#080c39;--dim:#3f3f52;--muted:#52525b;--border:#e4e4e7;--strong:#d4d4d8;--accent:#033ddc;--hover:#0231b4;--focus:rgba(3,61,220,.22);--ok:#047857;--danger:#b42335;font-family:"SF Pro Display","SF Pro Text",-apple-system,BlinkMacSystemFont,"Inter","Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:14px;line-height:1.5}
@media(prefers-color-scheme:dark){:root{--bg:#080c39;--surface:#10164a;--subtle:#171e59;--text:#f8f8fc;--dim:#d1d5ee;--muted:#a7aecc;--border:#27306b;--strong:#3a468a;--accent:#315ee8;--hover:#2455e6;--focus:rgba(108,140,255,.34);--ok:#34d399;--danger:#f87171}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text)}[hidden]{display:none!important}
.shell{width:min(1100px,100%);margin:0 auto;padding:32px 32px 76px}.header{display:flex;justify-content:space-between;align-items:center;gap:24px;padding-bottom:28px;border-bottom:1px solid var(--border)}
.wordmark{font-size:32px;letter-spacing:-.04em;line-height:1.1;font-weight:750}.wordmark span{font-weight:400}.product{color:var(--dim);font-size:14px;margin-top:6px}.running{display:flex;align-items:center;gap:8px;color:var(--dim);font-size:13px}.running:before{content:"";width:7px;height:7px;border-radius:50%;background:var(--ok)}
.intro{padding:30px 0 24px}h1{font-size:28px;letter-spacing:-.02em;font-weight:680;margin:0 0 8px}h2{font-size:18px;font-weight:650;margin:0}p{margin:0;color:var(--dim)}.grid{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:24px;align-items:start}.panel{border:1px solid var(--border);border-radius:8px;background:var(--surface);padding:24px}.panel-header{margin-bottom:24px}.panel-header p{margin-top:6px}.stack{display:grid;gap:18px}label{display:block;font-weight:550;color:var(--text)}input,select,button{font:inherit}input,select{display:block;width:100%;min-height:42px;margin-top:7px;padding:10px 12px;border:1px solid var(--strong);border-radius:6px;background:var(--surface);color:var(--text)}input:hover,select:hover{border-color:var(--accent)}input:focus-visible,select:focus-visible,button:focus-visible,a:focus-visible,summary:focus-visible{outline:none;box-shadow:0 0 0 3px var(--focus);border-color:var(--accent)}button,.button{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:42px;padding:10px 16px;border:1px solid var(--strong);border-radius:6px;background:var(--surface);color:var(--text);cursor:pointer;font-weight:600;text-decoration:none}button:hover,.button:hover{border-color:var(--accent);background:var(--subtle)}.primary{background:var(--accent);border-color:var(--accent);color:white}.primary:hover{background:var(--hover);color:white}button:disabled{opacity:.55;cursor:wait}.full{width:100%}fieldset{border:0;padding:0;margin:0;min-width:0}fieldset label+label{margin-top:16px}.hint{font-size:12px;color:var(--muted);margin-top:8px}.actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.actions .hint{margin:0}.divider{border-top:1px solid var(--border);margin-top:22px;padding-top:20px}details>summary{cursor:pointer;font-weight:550;color:var(--dim);padding:4px 0}details[open]>summary{margin-bottom:16px}details .stack{gap:14px}.address{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;color:var(--dim);overflow-wrap:anywhere;margin:8px 0 18px}.copy-row{display:flex;gap:8px;align-items:end;margin-top:8px}.copy-row input{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;margin:0;min-width:0}.copy-row button{flex-shrink:0}.connection{padding-top:20px}.connection label{font-size:13px}.text-button{border:0;padding:0;min-height:30px;background:transparent!important;color:var(--accent);font-weight:500}.import{margin-top:24px}.import form{max-width:640px}.status{color:var(--ok);font-size:13px;white-space:pre-wrap;margin-top:14px;min-height:0}.status:empty{display:none}.status.error{color:var(--danger)}footer{position:fixed;right:16px;bottom:12px;font-size:12px;color:var(--muted);background:var(--bg);padding:2px 6px;border-radius:4px}
@media(max-width:740px){.shell{padding:24px 18px 60px}.header{align-items:flex-start}.running{max-width:130px}.grid{grid-template-columns:1fr;gap:18px}.panel{padding:20px}.intro{padding-top:24px}h1{font-size:25px}}
@media(prefers-reduced-motion:no-preference){html{scroll-behavior:smooth}button,.button,input,select{transition:background .14s,border-color .14s}}
</style></head><body><div class="shell">
<header class="header"><div><div class="wordmark">ARISE<span>Kit</span></div><div class="product">Local runner</div></div><div class="running">Running on this computer</div></header>
<main><section class="intro"><h1>Open your benchmark</h1><p>Import your authoring bundle to open its local results workspace. Configure a provider for runs that require one.</p></section>
<div class="grid">
<section class="panel" aria-labelledby="provider-heading"><div class="panel-header"><h2 id="provider-heading">Provider connection</h2><p>Use the provider selected in your benchmark plan.</p></div>
<form id="provider-form" class="stack"><label>Model provider<select id="provider"><option value="openrouter">OpenRouter</option><option value="openai">OpenAI</option><option value="gemini">Google Gemini</option><option value="azure">Azure OpenAI</option><option value="reference">Reference run (no API key)</option></select></label>
<fieldset data-provider="openrouter"><label>OpenRouter API key<input name="OPENROUTER_API_KEY" type="password" autocomplete="off" placeholder="Enter your OpenRouter API key" required></label></fieldset>
<fieldset data-provider="openai" hidden><label>OpenAI API key<input name="OPENAI_API_KEY" type="password" autocomplete="off" placeholder="Enter your OpenAI API key" disabled required></label></fieldset>
<fieldset data-provider="gemini" hidden><label>Gemini API key<input name="GEMINI_API_KEY" type="password" autocomplete="off" placeholder="Enter your Gemini API key" disabled required></label></fieldset>
<fieldset data-provider="azure" hidden><label>Azure API base<input name="AZURE_API_BASE" type="url" placeholder="https://your-resource.openai.azure.com" disabled required></label><label>Azure API version<input name="AZURE_API_VERSION" placeholder="API version from your deployment" disabled required></label><label>Azure API key<input name="AZURE_API_KEY" type="password" autocomplete="off" disabled></label><label>Azure AD token<input name="AZURE_AD_TOKEN" type="password" autocomplete="off" disabled></label></fieldset>
<p id="reference-hint" hidden>No provider key is needed for a reference run.</p>
<div><button type="submit" class="primary" id="save-credentials">Save provider settings</button><p class="hint">Settings stay in this runner until it closes.</p></div>
</form><p id="provider-status" class="status" role="status" aria-live="polite"></p></section>
<aside class="panel" aria-labelledby="chat-heading"><div class="panel-header"><h2 id="chat-heading">Authoring chat</h2><p>Connect an authoring client if your workflow uses one.</p></div>
<div class="hint">Authoring site</div><div class="address" id="chat-address"></div><a id="continue-chat" class="button primary full" data-url="__CHAT_URL__" hidden>Continue in authoring chat</a>
<section id="runner-connection" class="connection" hidden><label for="runner-link">Runner connection link</label><div class="copy-row"><input id="runner-link" readonly><button type="button" id="copy-runner" aria-label="Copy connection link">Copy</button></div><p class="hint">Paste this under Benchmark runs in an existing chat.</p></section>
<div class="divider"><button type="button" id="show-runner" class="text-button">Show connection link</button><details><summary>Set authoring chat</summary><form id="chat-form" class="stack"><label>Authoring chat URL<input id="chat-url" type="url" value="__CHAT_URL__" required></label><p class="hint">Use your benchmark chat address, including its port for a local checkout.</p><button type="submit" id="save-chat">Save and continue</button></form></details></div><p id="status" class="status" role="status" aria-live="polite"></p></aside>
</div>
<details class="panel import" open><summary>Import a benchmark bundle</summary><form id="setup" class="stack"><p>Open a bundle saved on another computer. Its plan, source files, and retained results stay together.</p><label>Authoring bundle<input id="bundle" type="file" accept=".zip" required></label><div><button id="open">Prepare and open benchmark</button></div></form><p id="import-status" class="status" role="status" aria-live="polite"></p></details>
<p class="hint" style="margin-top:24px">Keep ARISEKit open while you work. Versions and results are saved on this computer.</p></main></div><footer>v__VERSION__</footer>
<script>
const storedToken=sessionStorage.getItem('arisekit-launcher-token');
const token=new URLSearchParams(location.hash.slice(1)).get('token')||storedToken||'';
if(token!==storedToken)sessionStorage.removeItem('arisekit-provider-saved');
sessionStorage.setItem('arisekit-launcher-token',token);history.replaceState(null,'',location.pathname);
const chatLink=document.getElementById('continue-chat');
const runnerLink=document.getElementById('runner-link');runnerLink.value=location.origin+'/#token='+token;
const chatAddress=document.getElementById('chat-address');
if(chatLink.dataset.url){
  chatLink.href=chatLink.dataset.url;
  chatLink.hash=new URLSearchParams({runner:runnerLink.value}).toString();
  chatAddress.textContent=new URL(chatLink.href).origin;
  chatLink.hidden=false;
} else {
  chatAddress.textContent='Optional. Set a chat URL to connect a compatible client.';
}
function status(id,text,error=false){const element=document.getElementById(id);element.textContent=text;element.classList.toggle('error',error);}
function showRunnerLink(){const section=document.getElementById('runner-connection');section.hidden=false;document.getElementById('show-runner').hidden=true;section.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'});}
async function request(path,payload){const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw Error(result.error);return result;}
document.getElementById('show-runner').addEventListener('click',showRunnerLink);
document.getElementById('copy-runner').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(runnerLink.value);status('status','Connection link copied.');}catch{runnerLink.focus();runnerLink.select();status('status','Copy the selected connection link.');}});
document.getElementById('chat-form').addEventListener('submit',async event=>{event.preventDefault();const button=document.getElementById('save-chat');button.disabled=true;try{const result=await request('/chat',{url:document.getElementById('chat-url').value.trim()});const destination=new URL(result.url);destination.hash=new URLSearchParams({runner:runnerLink.value}).toString();location.assign(destination.href);}catch(error){status('status',error.message,true);}finally{button.disabled=false;}});
const provider=document.getElementById('provider');provider.addEventListener('change',()=>{document.querySelectorAll('[data-provider]').forEach(fieldset=>{fieldset.hidden=fieldset.dataset.provider!==provider.value;fieldset.querySelectorAll('input').forEach(input=>input.disabled=fieldset.hidden);});document.getElementById('reference-hint').hidden=provider.value!=='reference';status('provider-status','');});
document.getElementById('provider-form').addEventListener('submit',async event=>{event.preventDefault();const button=document.getElementById('save-credentials');const credentials={};document.querySelectorAll('input[name]:not(:disabled)').forEach(input=>{if(input.value.trim())credentials[input.name]=input.value.trim();});if(provider.value==='azure'&&!credentials.AZURE_API_KEY&&!credentials.AZURE_AD_TOKEN){status('provider-status','Enter an Azure API key or AD token.',true);return;}button.disabled=true;try{await request('/connection',{credentials});document.querySelectorAll('input[name]').forEach(input=>input.value='');sessionStorage.setItem('arisekit-provider-saved','1');showRunnerLink();status('provider-status','Provider settings saved.');status('status','Your connection link is ready to copy.');}catch(error){status('provider-status',error.message,true);}finally{button.disabled=false;}});
document.getElementById('setup').addEventListener('submit',async event=>{event.preventDefault();const button=document.getElementById('open');button.disabled=true;try{const file=document.getElementById('bundle').files[0];if(!file||file.size>67108864)throw Error('Choose an authoring ZIP no larger than 64 MiB.');status('import-status','Preparing your benchmark…');const archive=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('Could not read the file.'));reader.readAsDataURL(file);});const result=await request('/open',{archive,credentials:{}});location.assign(result.url);}catch(error){status('import-status',error.message,true);button.disabled=false;}});
if(sessionStorage.getItem('arisekit-provider-saved')){document.getElementById('runner-connection').hidden=false;document.getElementById('show-runner').hidden=true;}
if(!token){status('status','Reopen ARISEKit to create a connection link.',true);document.querySelectorAll('button').forEach(button=>button.disabled=true);chatLink.removeAttribute('href');}
</script></body></html>'''
